using System;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Documents;
partial class TerminalWindow {
 TaskbarRow taskbarDragging;string taskbarDragToken;StackPanel compactOrderHost;TaskbarInsertionAdorner orderAdorner;AdornerLayer orderLayer;
 void ClearOrderAdorner(){if(orderAdorner!=null&&orderLayer!=null)orderLayer.Remove(orderAdorner);orderAdorner=null;orderLayer=null;}
 void ShowOrderAdorner(Border frame,bool after,int target){if(orderAdorner==null||!Object.ReferenceEquals(orderAdorner.AdornedElement,frame)){ClearOrderAdorner();orderLayer=AdornerLayer.GetAdornerLayer(frame);if(orderLayer==null)return;orderAdorner=new TaskbarInsertionAdorner(frame);orderLayer.Add(orderAdorner);}orderAdorner.After=after;orderAdorner.Index=target;orderAdorner.InvalidateVisual();}
 void BuildCompactTaskbarOrder(Panel body,List<TaskbarRow> rows,StackPanel detailedHost){SettingDescription(body,"全部项目在此集中排序。拖动把手，蓝线与“第几位”标出落点；未显示的项目也可排序。修改后仍需应用并保存。");compactOrderHost=new StackPanel();body.Children.Add(compactOrderHost);foreach(var row in rows){var line=new WrapPanel();var frame=new Border{Child=line,CornerRadius=new CornerRadius(6),BorderThickness=new Thickness(1),Margin=new Thickness(0,1,0,1)};frame.SetResourceReference(Border.BorderBrushProperty,"DeskLine");row.SortView=frame;compactOrderHost.Children.Add(frame);AddTaskbarOrderHandle(line,frame,row,rows,detailedHost);var grip=(Border)line.Children[0];grip.Height=23;grip.Child=new TextBlock{Text="⠿",FontSize=18,HorizontalAlignment=HorizontalAlignment.Center};var label=new TextBlock{FontSize=12,VerticalAlignment=VerticalAlignment.Center};line.Children.Add(label);Action update=()=>label.Text=(row.Enabled.IsChecked==true?"● ":"○ ")+(row.Key=="download"?"下载速度":row.Key=="upload"?"上传速度":MonitorEngine.Label(row.Key))+"  ·  "+row.Label.Text+(row.Enabled.IsChecked==true?"":"（未显示）");update();row.Enabled.Click+=(s,e)=>update();row.Label.TextChanged+=(s,e)=>update();}}

 DataObject TaskbarDragData(TaskbarRow row){taskbarDragging=row;taskbarDragToken=Guid.NewGuid().ToString("N");return new DataObject("Conan.TaskbarOrder",taskbarDragToken);}
 void MoveTaskbarRow(List<TaskbarRow> rows,StackPanel host,TaskbarRow row,int target){int source=rows.IndexOf(row);if(source<0||target<0||target>=rows.Count||target==source)return;rows.RemoveAt(source);rows.Insert(target,row);host.Children.Remove(row.View);host.Children.Insert(target+1,row.View);if(compactOrderHost!=null&&row.SortView!=null){compactOrderHost.Children.Remove(row.SortView);compactOrderHost.Children.Insert(target,row.SortView);}if(refreshTaskbarPreview!=null)refreshTaskbarPreview();}
 void AddTaskbarOrderHandle(WrapPanel line,Border frame,TaskbarRow row,List<TaskbarRow> rows,StackPanel host){
  var grip=TaskbarName(new Border{Child=new TextBlock{Text="⠿",FontSize=24,FontFamily=new FontFamily("Segoe UI Symbol"),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center},Width=32,Height=36,Background=Brushes.Transparent,Cursor=Cursors.SizeAll,ToolTip="按住拖动排序；也可使用右侧上下按钮",Tag=row},"拖动排序-"+row.Key);line.Children.Add(grip);frame.AllowDrop=true;Point? start=null;
  grip.PreviewMouseLeftButtonDown+=(s,e)=>{start=e.GetPosition(grip);e.Handled=true;};grip.PreviewMouseLeftButtonUp+=(s,e)=>start=null;
  grip.MouseMove+=(s,e)=>{if(!start.HasValue||e.LeftButton!=MouseButtonState.Pressed)return;var p=e.GetPosition(grip);if(Math.Abs(p.X-start.Value.X)<SystemParameters.MinimumHorizontalDragDistance&&Math.Abs(p.Y-start.Value.Y)<SystemParameters.MinimumVerticalDragDistance)return;start=null;try{DragDrop.DoDragDrop(grip,TaskbarDragData(row),DragDropEffects.Move);}finally{ClearOrderAdorner();taskbarDragging=null;taskbarDragToken=null;foreach(var item in rows)foreach(var border in new[]{item.View as Border,item.SortView})if(border!=null){border.Background=Brushes.Transparent;border.SetResourceReference(Border.BorderBrushProperty,"DeskLine");}}};
  Func<DragEventArgs,bool> accepted=e=>taskbarDragging!=null&&rows.Contains(taskbarDragging)&&e.Data.GetDataPresent("Conan.TaskbarOrder",false)&&Convert.ToString(e.Data.GetData("Conan.TaskbarOrder",false))==taskbarDragToken;
  frame.PreviewDragOver+=(s,e)=>{e.Handled=true;e.Effects=accepted(e)?DragDropEffects.Move:DragDropEffects.None;if(e.Effects==DragDropEffects.None)return;int target=TaskbarOrderLogic.Target(rows.IndexOf(taskbarDragging),rows.IndexOf(row),e.GetPosition(frame).Y>frame.ActualHeight/2,rows.Count);ShowOrderAdorner(frame,e.GetPosition(frame).Y>frame.ActualHeight/2,target);frame.SetResourceReference(Border.BackgroundProperty,"DeskSelected");frame.SetResourceReference(Border.BorderBrushProperty,"DeskAccent");var parent=VisualTreeHelper.GetParent(frame);while(parent!=null&&!(parent is ScrollViewer))parent=VisualTreeHelper.GetParent(parent);var scroll=parent as ScrollViewer;if(scroll!=null){double y=e.GetPosition(scroll).Y;if(y<55)scroll.ScrollToVerticalOffset(scroll.VerticalOffset-24);else if(y>scroll.ActualHeight-55)scroll.ScrollToVerticalOffset(scroll.VerticalOffset+24);}};
  frame.DragLeave+=(s,e)=>{ClearOrderAdorner();frame.Background=Brushes.Transparent;frame.SetResourceReference(Border.BorderBrushProperty,"DeskLine");};
  frame.PreviewDrop+=(s,e)=>{ClearOrderAdorner();e.Handled=true;frame.Background=Brushes.Transparent;frame.SetResourceReference(Border.BorderBrushProperty,"DeskLine");if(!accepted(e)){e.Effects=DragDropEffects.None;return;}int target=TaskbarOrderLogic.Target(rows.IndexOf(taskbarDragging),rows.IndexOf(row),e.GetPosition(frame).Y>frame.ActualHeight/2,rows.Count);MoveTaskbarRow(rows,host,taskbarDragging,target);e.Effects=DragDropEffects.Move;taskbarDragging=null;taskbarDragToken=null;};
 }
}
